list_tax_custom_profiles.code:
var response = await client.TaxCustomProfiles.ListTaxCustomProfilesAsync(
    new Dictionary<string, object?> { ["limit"] = 20 });
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
foreach (var customProfile in ((IReadOnlyList<object?>)body["custom_profiles"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{customProfile["id"]} {customProfile["name"]} {customProfile["rate_rules_count"]}");

create_tax_custom_profile.code:
var response = await client.TaxCustomProfiles.CreateTaxCustomProfileAsync(new Dictionary<string, object?>
{
    ["custom_profile"] = new Dictionary<string, object?> { ["name"] = "Wholesale customers", ["description"] = "Rates for wholesale accounts" },
});
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var customProfile = (IReadOnlyDictionary<string, object?>)body["custom_profile"]!;
Console.WriteLine(customProfile["id"]);

get_tax_custom_profile.code:
var response = await client.TaxCustomProfiles.GetTaxCustomProfileAsync(1);
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var customProfile = (IReadOnlyDictionary<string, object?>)body["custom_profile"]!;
Console.WriteLine(customProfile["name"]);
foreach (var rateRule in ((IReadOnlyList<object?>)customProfile["rate_rules"]!).Cast<IReadOnlyDictionary<string, object?>>())
    Console.WriteLine($"{rateRule["id"]} {rateRule["name"]} {rateRule["zones_count"]}");

